-- T1 (C1, exploratory): scalar subquery inside a WHERE function; post-replacement root is Item_func.
-- Sensitive: root has PROP_SUBQUERY before replacement, none after. Observable: residual has_subquery() in trace/EXPLAIN.
CREATE DATABASE IF NOT EXISTS s2_c1;
USE s2_c1;
DROP TABLE IF EXISTS t1_outer, t1_inner;
CREATE TABLE t1_outer (id INT PRIMARY KEY, v INT NOT NULL);
CREATE TABLE t1_inner (id INT PRIMARY KEY, w INT NOT NULL);
INSERT INTO t1_outer VALUES (1,10),(2,20),(3,30);
INSERT INTO t1_inner VALUES (1,5),(2,25),(3,35);
-- Target: WHERE expression is a function over a scalar subquery.
SELECT id, v FROM t1_outer
 WHERE (v + (SELECT w FROM t1_inner WHERE t1_inner.id = t1_outer.id)) > 20;
-- Contrast: same predicate without subquery (no replace_subquery_in_expr path).
SELECT id, v FROM t1_outer WHERE v + 5 > 20;
-- Diagnostic: trace to inspect residual subquery handling on the post-replacement item.
SET optimizer_trace='enabled=on';
SELECT id, v FROM t1_outer
 WHERE (v + (SELECT w FROM t1_inner WHERE t1_inner.id = t1_outer.id)) > 20;
SELECT TRACE FROM information_schema.OPTIMIZER_TRACE;
SET optimizer_trace='enabled=off';
DROP TABLE t1_outer, t1_inner;
-- T2 (C1, exploratory): scalar subquery inside a SELECT-list function; exercises the SELECT-expression
-- caller at sql_resolver.cc:7654-7693 (rollup unwrap not used here). Same sensitive property as T1.
USE s2_c1;
DROP TABLE IF EXISTS t2_outer, t2_inner;
CREATE TABLE t2_outer (id INT PRIMARY KEY, v INT NOT NULL);
CREATE TABLE t2_inner (id INT PRIMARY KEY, w INT NOT NULL);
INSERT INTO t2_outer VALUES (1,10),(2,20),(3,30);
INSERT INTO t2_inner VALUES (1,5),(2,25),(3,35);
-- Target: SELECT-list function over scalar subquery.
SELECT id, (v + (SELECT w FROM t2_inner WHERE t2_inner.id = t2_outer.id)) AS s
  FROM t2_outer ORDER BY id;
-- Contrast: same SELECT-list function without subquery.
SELECT id, (v + 5) AS s FROM t2_outer ORDER BY id;
SET optimizer_trace='enabled=on';
SELECT id, (v + (SELECT w FROM t2_inner WHERE t2_inner.id = t2_outer.id)) AS s
  FROM t2_outer ORDER BY id;
SELECT TRACE FROM information_schema.OPTIMIZER_TRACE;
SET optimizer_trace='enabled=off';
DROP TABLE t2_outer, t2_inner;
-- T3 (C2): IS NULL over a non-nullable window-function child in a buffered window.
-- Sensitive: child is non-nullable (SUM OVER with frame over NOT NULL column) so parent skips propagation;
-- target propagates PROP_WINDOW_FUNCTION to the IS NULL wrapper. Oracle: window result over original rows, then IS NULL.
USE s2_c1;
DROP TABLE IF EXISTS t3_w;
CREATE TABLE t3_w (id INT PRIMARY KEY, g INT NOT NULL, x INT NOT NULL);
INSERT INTO t3_w VALUES (1,1,10),(2,1,20),(3,2,30),(4,2,40),(5,1,50);
-- Target: IS NULL wrapper around a window function.
SELECT id, g, x,
       IS NULL(SUM(x) OVER (PARTITION BY g ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW)) AS isn
  FROM t3_w ORDER BY id;
-- Contrast: bare window function (no IS NULL wrapper) — same window, no wrapper property question.
SELECT id, g, x,
       SUM(x) OVER (PARTITION BY g ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS s
  FROM t3_w ORDER BY id;
DROP TABLE t3_w;
-- T4 (C2): IS NULL over a non-nullable window child with a different frame (UNBOUNDED PRECEDING),
-- exercising a different buffering boundary than T3. Same sensitive property, different frame condition.
USE s2_c1;
DROP TABLE IF EXISTS t4_w;
CREATE TABLE t4_w (id INT PRIMARY KEY, g INT NOT NULL, x INT NOT NULL);
INSERT INTO t4_w VALUES (1,1,10),(2,1,20),(3,2,30),(4,2,40),(5,1,50);
-- Target: IS NULL over running SUM with UNBOUNDED PRECEDING frame.
SELECT id, g, x,
       IS NULL(SUM(x) OVER (PARTITION BY g ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) AS isn
  FROM t4_w ORDER BY id;
-- Contrast: same window without IS NULL wrapper.
SELECT id, g, x,
       SUM(x) OVER (PARTITION BY g ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS s
  FROM t4_w ORDER BY id;
DROP TABLE t4_w;
-- T5 (C2): IS NULL over a non-nullable window child using a different window function (COUNT OVER)
-- to vary the child item type while keeping the non-nullable property. Same sensitive property.
USE s2_c1;
DROP TABLE IF EXISTS t5_w;
CREATE TABLE t5_w (id INT PRIMARY KEY, g INT NOT NULL, x INT NOT NULL);
INSERT INTO t5_w VALUES (1,1,10),(2,1,20),(3,2,30),(4,2,40),(5,1,50);
-- Target: IS NULL over COUNT window (COUNT is non-nullable).
SELECT id, g, x,
       IS NULL(COUNT(x) OVER (PARTITION BY g ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW)) AS isn
  FROM t5_w ORDER BY id;
-- Contrast: same window without IS NULL wrapper.
SELECT id, g, x,
       COUNT(x) OVER (PARTITION BY g ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS c
  FROM t5_w ORDER BY id;
DROP TABLE t5_w;
DROP DATABASE s2_c1;
